-- softly-hotkey: @HOTKEY@
-- softly-mode: @MODE@
-- @SUMMARY@
-- Generated by the Softly plugin (helpers/control.py) from
-- hypr/module.lua; change the key in the plugin's settings, not here. Loaded
-- by one marked line at the end of hyprland.lua; "Remove setup" in the panel
-- takes both away.
@KEYS@

-- Esc cancels, bound only while the pill is on screen, so Esc reaches apps otherwise.
local softly_esc = nil
hl.on("layer.opened", function(layer)
  if layer.namespace == "softly" and not softly_esc then
    softly_esc = hl.bind("ESCAPE", hl.dsp.exec_cmd("omarchy-shell io.github.denonmaryland.softly cancel"), { description = "Softly: cancel dictation" })
  end
end)
hl.on("layer.closed", function(layer)
  if layer.namespace == "softly" and softly_esc then
    softly_esc:unbind()
    softly_esc = nil
  end
end)
